ON CONFLICT (osm_relation_id) DO UPDATE SET boundary = EXCLUDED.boundary, name = EXCLUDED.name, code = EXCLUDED.code;

DO $$
DECLARE covered_km2 numeric;
BEGIN
    SELECT ST_Area(ST_Union(z.boundary)::geography) / 1e6 INTO covered_km2
    FROM zones z JOIN cities c ON c.id = z.city_id
    WHERE c.code = 'BB' AND z.level = 1;
    IF covered_km2 < 606 THEN
        RAISE EXCEPTION 'Pokrivenost nivoa 1 za Bajina Bašta je samo % km2, ocekivano ~673', round(covered_km2);
    END IF;
END $$;
